#include <bits/stdc++.h>
using namespace std;
int main(){
    int n,r,tc=0;
    while (cin>>n>>r && (n||r)) {
        tc++;
        vector<vector<int>> cap(n+1, vector<int>(n+1,0));
        for (int i=0;i<r;i++){
            int c1,c2,p; cin>>c1>>c2>>p;
            cap[c1][c2] = max(cap[c1][c2], p);
            cap[c2][c1] = max(cap[c2][c1], p);
        }
        int s,d,t; cin>>s>>d>>t;
        vector<int> best(n+1,0); vector<bool> done(n+1,false);
        best[s] = INT_MAX;
        for (int iter=0; iter<n; iter++){
            int u=-1;
            for (int i=1;i<=n;i++) if(!done[i] && (u==-1||best[i]>best[u])) u=i;
            if (u==-1 || best[u]==0) break;
            done[u]=true;
            for (int v=1; v<=n; v++) if(cap[u][v]>0) best[v]=max(best[v], min(best[u], cap[u][v]));
        }
        int trips = (t + best[d] - 1) / best[d];
        if (tc>1) cout << "\n";
        cout << "Scenario #" << tc << "\n";
        cout << "Minimum Number of Trips = " << trips << "\n";
    }
}

